$ node -e "
const fs=require('fs');
const src=fs.readFileSync('src/screens/FieldTab.jsx','utf8');
const m=src.match(/const X = \{[\s\S]*?\n\};/)[0];
const X=eval('('+m.replace('const X = ','').replace(/;\$/,'')+')');
const render=(lang,n,k)=>{const x=X[lang];return x.summary.replace('{n}',n).replace('{k}',k).split('{unit}').join(n===1?x.unitOne:x.unitMany);};
for(const lang of ['en','hi']) for(const [n,k] of [[1,0],[1,1],[3,1],[5,4],[12,0]]) console.log(lang,'n='+n,'k='+k,'->',render(lang,n,k));
"
